import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { env } from "../env";

/**
 * Where uploaded bytes live. "local" writes under STORAGE_DIR (mount a volume in production).
 * Keys are generated by us, never taken from the user, and are checked to stay inside the storage folder.
 */
function resolveKey(key: string) {
  if (!/^[a-z0-9/_.-]+$/i.test(key) || key.includes("..")) throw new Error(`Invalid storage key: ${key}`);
  const root = path.resolve(env().STORAGE_DIR);
  const full = path.resolve(root, key);
  if (!full.startsWith(root + path.sep)) throw new Error(`Storage key escapes the storage folder: ${key}`);
  return full;
}

export async function putObject(key: string, bytes: Uint8Array) {
  const full = resolveKey(key);
  await mkdir(path.dirname(full), { recursive: true });
  await writeFile(full, bytes, { flag: "wx" });
}

export async function getObject(key: string): Promise<Buffer> {
  return readFile(resolveKey(key));
}

export async function deleteObject(key: string) {
  await rm(resolveKey(key), { force: true });
}
